(6867781, 1033904, 3102, '<td valign="top">b</td>', 'b', '2012-09-22 23:44:21.000000', NULL, 1),
(6867782, 1033873, 10785, '<td valign="top">Good documentary photo. I would have no idea that this was a part of the mating ritual of the manatee if the title were not there. This looks like a manatee on a log and having two faces showing would have strengthened the message somewhat.</td>', 'Good documentary photo. I would have no idea that this was a part of the mating ritual of the manatee if the title were not there. This looks like a manatee on a log and having two faces showing would have strengthened the message somewhat.', '2012-09-22 23:45:30.000000', NULL, 1),
(6867792, 1033941, 138630, '<td valign="top">I like everything about this desolate scene - the old abandoned building, the uncut field, the dramatic sky.  The composition suits it well.  One of my top three.  Voted earlier.</td>', 'I like everything about this desolate scene - the old abandoned building, the uncut field, the dramatic sky.  The composition suits it well.  One of my top three.  Voted earlier.', '2012-09-23 00:20:39.000000', NULL, 1),
(6867793, 1033909, 138630, '<td valign="top">A little too pretty for me normally but I kept coming back and it finally ended up as one of my top choices.  The smoothness of the water, the pink tones, the extreme simplicity of the subject and composition all appeal.  Voted earlier.<br/>edited to correct spelling<br/><br/><i>Message edited by author 2012-09-24 00:11:13.</i></td>', 'A little too pretty for me normally but I kept coming back and it finally ended up as one of my top choices.  The smoothness of the water, the pink tones, the extreme simplicity of the subject and composition all appeal.  Voted earlier.edited to correct spelling', '2012-09-23 00:22:24.000000', '2012-09-24 01:11:13.000000', 1),
(6867794, 1033919, 138630, '<td valign="top">Superb, crisp detail on both the leaves and the dragonfly.  Love the coppery color of the leaves and their unusual shapes.  One of my top three.  Voted earlier.</td>', 'Superb, crisp detail on both the leaves and the dragonfly.  Love the coppery color of the leaves and their unusual shapes.  One of my top three.  Voted earlier.', '2012-09-23 00:23:26.000000', NULL, 1),
